/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `reviews` (
  `id_ulasan` int(11) NOT NULL AUTO_INCREMENT,
  `id_penumpang` int(11) DEFAULT NULL,
  `id_perjalanan` int(11) DEFAULT NULL,
  `rating` int(11) DEFAULT NULL CHECK (`rating` between 1 and 5),
  `komentar` text DEFAULT NULL,
  `tanggal` date DEFAULT NULL,
  `waktu` time DEFAULT NULL,
  PRIMARY KEY (`id_ulasan`),
  KEY `id_penumpang` (`id_penumpang`),
  KEY `id_perjalanan` (`id_perjalanan`),
  CONSTRAINT `reviews_ibfk_1` FOREIGN KEY (`id_penumpang`) REFERENCES `users` (`id_pengguna`),
  CONSTRAINT `reviews_ibfk_2` FOREIGN KEY (`id_perjalanan`) REFERENCES `tripsss` (`id_perjalanan`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
