--
-- Table structure for table `trips`
--

DROP TABLE IF EXISTS `trips`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `trips` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `trip_id` varchar(255) NOT NULL,
  `order_id` varchar(30) NOT NULL,
  `driver_id` int(11) NOT NULL,
  `email` varchar(20) NOT NULL,
  `name` varchar(255) NOT NULL,
  `time` int(11) NOT NULL,
  `distance` decimal(10,2) NOT NULL,
  `start_point` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`start_point`)),
  `finishing_point` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`finishing_point`)),
  `total_payment` decimal(10,2) NOT NULL,
  `driver_profit` decimal(10,2) NOT NULL,
  `company_profit` decimal(10,2) NOT NULL,
  `status` enum('pending','ongoing','completed','cancelled') NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `is_accepted` enum('canceled','accepted') NOT NULL DEFAULT 'accepted',
  PRIMARY KEY (`id`),
  UNIQUE KEY `trip_id` (`trip_id`),
  KEY `fk_trip_email` (`email`),
  CONSTRAINT `fk_trip_email` FOREIGN KEY (`email`) REFERENCES `users` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=153 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
